"""Choosing an item's files (R10, R11, F7): originals by default, never archive.org's generated byproducts,
private files or DRM-wrapped copies, narrowed by format and name patterns."""

import fnmatch
from dataclasses import dataclass, field

from .rights import forbidden_file

# Formats archive.org generates for its own pages and indexes, never worth downloading (R11). Matched as
# substrings of the file's format, case-insensitively.
JUNK_FORMATS = (
    "spectrogram", "columbia peaks", "essentia", "thumbnail", "animated gif", "hocr", "chocr",
    "ocr page index", "ocr search text", "page numbers json", "scandata", "djvu xml",
    "content addressable", "car transmit", "storj", "archive bittorrent", "activity log", "item tile",
    "item image", "metadata",
)
# Names archive.org gives its byproducts, whatever their format says.
JUNK_SUFFIXES = ("_meta.sqlite", "_reviews.xml", ".asr.js", "_spectrogram.png", ".afpk", ".log", ".trigger",
                 "_files.xml", "_meta.xml", "_archive.torrent")
JUNK_PARTS = (".thumbs/", "_thumbs/", "__ia_thumb.jpg")
JUNK_PREFIXES = ("history/",)  # earlier versions of replaced files, kept by archive.org

# Kept with every item as the record of what was downloaded (F16). _files.xml has no size, and the MD5 it
# lists for itself can't be right, so it's never checked against it (F15c).
RECORD_FILES = ("_meta.xml", "_files.xml")
TILE = "__ia_thumb.jpg"


def junk(f: dict) -> bool:
    name, fmt = f.get("name", ""), f.get("format", "").lower()
    return (any(j in fmt for j in JUNK_FORMATS) or name.lower().endswith(JUNK_SUFFIXES)
            or any(p in name for p in JUNK_PARTS) or name.startswith(JUNK_PREFIXES))


@dataclass
class Profile:
    """What to take from an item. A handler starts from its own; the command line adjusts it."""
    originals: bool = True  # False: derivatives too (--all)
    formats: list[str] = field(default_factory=list)  # archive.org format names, e.g. "h.264"; any if empty
    globs: list[str] = field(default_factory=list)  # names to take; any if empty
    exclude: list[str] = field(default_factory=list)  # names never to take
    empty: bool = False  # take empty files (archive.org lists some, e.g. blank subtitles)


@dataclass
class Selection:
    files: list[dict]
    record: list[dict]  # _meta.xml and _files.xml
    tile: dict | None
    private: int = 0  # private files skipped (F15c reports the count)
    encrypted: int = 0

    @property
    def size(self) -> int:
        return sum(size_of(f) for f in self.files + self.record + ([self.tile] if self.tile else []))


def select(item, profile: Profile | None = None) -> Selection:
    profile = profile or Profile()
    chosen, private, encrypted = [], 0, 0
    formats = [x.lower() for x in profile.formats]
    for f in item.files:
        why = forbidden_file(f)
        if why == "private":
            private += 1
            continue
        if why:
            encrypted += 1
            continue
        if junk(f) or f.get("source") == "metadata":
            continue
        if profile.originals and f.get("source") != "original" and not formats:
            continue
        if formats and f.get("format", "").lower() not in formats:
            continue
        name = f.get("name", "")
        if profile.globs and not any(fnmatch.fnmatchcase(name, g) for g in profile.globs):
            continue
        if any(fnmatch.fnmatchcase(name, g) for g in profile.exclude):
            continue
        if not profile.empty and size_of(f) == 0 and f.get("size") is not None:
            continue
        chosen.append(f)
    record = [f for f in item.files if f.get("name", "").endswith(tuple(item.identifier + r for r in RECORD_FILES))]
    tile = next((f for f in item.files if f.get("name") == TILE and not forbidden_file(f)), None)
    return Selection(chosen, record, tile, private, encrypted)


def size_of(f: dict) -> int:
    try:
        return int(f.get("size") or 0)
    except (TypeError, ValueError):
        return 0
